secret_helper.s:
the secret abstraction and the platform types. every secret in this repo is read through get_secret, so a cloudflare secrets-store binding and a plain .env string are interchangeable and no call site ever unwraps a binding by hand.

CREATE src/lib/secret.ts:

export type SecretVal = string | { get?: () => Promise<string> } | undefined;

export async function get_secret(v: SecretVal): Promise<string> {
	if (typeof v === 'string' && v) return v;
	if (v && typeof v === 'object' && typeof v.get === 'function') {
		const s = await v.get();
		if (s) return s;
	}
	throw new Error('missing secret');
}

