db_lib.s:
the six query helpers every server file in this repo uses. nothing else talks to D1 directly.

CREATE src/lib/db.ts:

export const uid = () => crypto.randomUUID();

export const now = () => Date.now();

export async function one<T>(db: D1Database, sql: string, ...a: unknown[]): Promise<T | null> {
	return (await db.prepare(sql).bind(...a).first()) as T | null;
}

export async function all<T>(db: D1Database, sql: string, ...a: unknown[]): Promise<T[]> {
	return ((await db.prepare(sql).bind(...a).all()).results ?? []) as T[];
}

export function run(db: D1Database, sql: string, ...a: unknown[]) {
	return db.prepare(sql).bind(...a).run();
}

export function active_season(db: D1Database) {
	return one<{ i: string; n: string }>(db, "select i, n from se where st = 'a' order by c desc limit 1");
}

export async function team_map(db: D1Database) {
	const rows = await all<{ i: string; n: string; ab: string; d: string }>(db, 'select i, n, ab, d from t');
	return Object.fromEntries(rows.map((r) => [r.i, r]));
}

every sql string in this repo is written inline at its call site and bound with ?, never built by concatenating or interpolating a value. there is no query builder and you must not add one — the gate greps for template-literal sql and fails on it.

session_lib.s:
the pure half of auth, so it can be unit tested without a request.

CREATE src/lib/session.ts:

export const SESSION_MS = 30 * 24 * 60 * 60 * 1000;

export function new_id(): string {
	return crypto.randomUUID();
}

export function cookie_str(id: string, max_age: number, secure: boolean): string {
	return `s=${id}; Path=/; HttpOnly; SameSite=Lax; Max-Age=${max_age}` + (secure ? '; Secure' : '');
}

export function clear_cookie(secure: boolean): string {
	return cookie_str('', 0, secure);
}

export function is_expired(x: number, now: number): boolean {
	return now >= x;
}

export function is_admin(u: { r: string } | null | undefined): boolean {
	return !!u && u.r === 'a';
}

note the exact cookie string the tests expect: name `s`, Path=/, HttpOnly, SameSite=Lax, Max-Age, and Secure appended only when secure is true. SameSite=Lax rather than Strict because the google callback is a cross-site redirect back into the site and Strict would drop the cookie.

place the planner's test:

  cp plan/tests/src/lib/session.test.ts.txt src/lib/session.test.ts

google_login.s:
google oauth end to end. callback path is /google — never /google/callback, that is a house rule.

FIRST: open .env. if GOOGLE_ID or GOOGLE_SECRET is still `replace_me`, real credentials are needed from the google cloud console and you cannot create them. run:
  plan mesh google_login --block "need real GOOGLE_ID and GOOGLE_SECRET in .env; authorised redirect uri http://localhost:5173/google and https://mesh.<subdomain>.workers.dev/google"
and stop. do not fake credentials, do not skip the step.

CREATE src/routes/login/+server.ts — builds the consent url and sets a short state cookie:

import { redirect } from '@sveltejs/kit';
import { get_secret } from '#lib/secret';
import { new_id } from '#lib/session';
import type { RequestHandler } from './$types';

export const GET: RequestHandler = async ({ url, platform, cookies }) => {
	const state = new_id();
	cookies.set('st', state, { path: '/', httpOnly: true, sameSite: 'lax', maxAge: 600, secure: url.protocol === 'https:' });
	const q = new URLSearchParams({
		client_id: await get_secret(platform!.env.GOOGLE_ID),
		redirect_uri: new URL('/google', url.origin).toString(),
		response_type: 'code',
		scope: 'openid email profile',
		state,
		prompt: 'select_account'
	});
	redirect(302, 'https://accounts.google.com/o/oauth2/v2/auth?' + q.toString());
};

CREATE src/routes/google/+server.ts — the callback. verifies state, swaps the code, upserts the user, opens a session:

import { redirect, error } from '@sveltejs/kit';
import { get_secret } from '#lib/secret';
import { new_id, cookie_str, SESSION_MS } from '#lib/session';
import { one, run, now } from '#lib/db';
import type { RequestHandler } from './$types';

export const GET: RequestHandler = async ({ url, platform, cookies, setHeaders }) => {
	const code = url.searchParams.get('code');
	if (!code || url.searchParams.get('state') !== cookies.get('st')) error(400, 'bad login');
	cookies.delete('st', { path: '/' });
	const db = platform!.env.DB;
	const res = await fetch('https://oauth2.googleapis.com/token', {
		method: 'POST',
		headers: { 'content-type': 'application/x-www-form-urlencoded' },
		body: new URLSearchParams({
			code,
			client_id: await get_secret(platform!.env.GOOGLE_ID),
			client_secret: await get_secret(platform!.env.GOOGLE_SECRET),
			redirect_uri: new URL('/google', url.origin).toString(),
			grant_type: 'authorization_code'
		})
	});
	if (!res.ok) error(502, 'google rejected the login');
	const tok = (await res.json()) as { access_token: string };
	const me = (await (
		await fetch('https://www.googleapis.com/oauth2/v3/userinfo', {
			headers: { authorization: 'Bearer ' + tok.access_token }
		})
	).json()) as { sub: string; email: string; name?: string };
	let u = await one<{ i: string }>(db, 'select i from u where g = ?', me.sub);
	if (!u) {
		const i = new_id();
		await run(db, 'insert into u (i, e, n, g, r, c) values (?, ?, ?, ?, ?, ?)', i, me.email, (me.name || me.email).toLowerCase(), me.sub, 'u', now());
		u = { i };
	}
	const s = new_id();
	await run(db, 'insert into ss (i, u, x) values (?, ?, ?)', s, u.i, now() + SESSION_MS);
	setHeaders({ 'set-cookie': cookie_str(s, SESSION_MS / 1000, url.protocol === 'https:') });
	redirect(303, '/me');
};

CREATE src/routes/logout/+server.ts — POST only, deletes the row and the cookie, redirects to /:

import { redirect } from '@sveltejs/kit';
import { clear_cookie } from '#lib/session';
import { run } from '#lib/db';
import type { RequestHandler } from './$types';

export const POST: RequestHandler = async ({ url, platform, cookies, setHeaders }) => {
	const s = cookies.get('s');
	if (s) await run(platform!.env.DB, 'delete from ss where i = ?', s);
	setHeaders({ 'set-cookie': clear_cookie(url.protocol === 'https:') });
	redirect(303, '/');
};

CREATE src/hooks.server.ts — resolves the session into event.locals.user on every request and guards the two protected trees:

import { redirect, error } from '@sveltejs/kit';
import { is_expired, is_admin } from '#lib/session';
import { one } from '#lib/db';
import type { Handle } from '@sveltejs/kit';

export const handle: Handle = async ({ event, resolve }) => {
	event.locals.user = null;
	const s = event.cookies.get('s');
	if (s && event.platform) {
		const row = await one<{ x: number; i: string; e: string; n: string; r: string }>(
			event.platform.env.DB,
			'select ss.x as x, u.i as i, u.e as e, u.n as n, u.r as r from ss join u on u.i = ss.u where ss.i = ?',
			s
		);
		if (row && !is_expired(row.x, Date.now())) event.locals.user = { i: row.i, e: row.e, n: row.n, r: row.r };
	}
	if (event.url.pathname.startsWith('/me') && !event.locals.user) redirect(303, '/login');
	if (event.url.pathname.startsWith('/admin') && !is_admin(event.locals.user)) error(403, 'admins only');
	return resolve(event);
};

